export type LayerType = 'hero-letter' | 'text' | 'media' | 'container' | 'button';

export interface BuildLayer {
  id: string;
  element: HTMLElement;
  rect: {
    top: number;
    left: number;
    width: number;
    height: number;
  };
  docTop: number;
  docLeft: number;
  type: LayerType;
  tagLabel: string;
  status: 'pending' | 'building' | 'done';
  assignedAgentId?: string;
  domIndex: number;
}

export interface Agent {
  id: string;
  name: string;
  color: string;
  x: number;
  y: number;
  targetX: number;
  targetY: number;
  state: 'entering' | 'idle' | 'flying' | 'building' | 'resting' | 'flying-away';
  currentLayerId?: string;
  taskProgress: number;
  taskDuration: number;
  restTimer: number;
  driftAngle: number;
  driftRadius: number;
  driftSpeed: number;
}

export interface Particle {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
  size: number;
  alpha: number;
  life: number;
  maxLife: number;
}

export interface RegistrationMark {
  x: number;
  y: number;
  id: string;
}

